124	    /**
125	     * Get a shuffled list of the free adjacent locations.
126	     * 
127	     * @param searchLocation Get locations adjacent to this.
128	     * @return A list of free adjacent locations.
129	     */
130	    public List<Location> getFreeAdjacentLocations(Location searchLocation)
131	    {
132	        // The list of free locations to be returned:
133	        List<Location> free = new ArrayList<>();
134	        
135	        List<Location> adjacentLocations = adjacentLocations(searchLocation);
136	        
137	        for (Location location : adjacentLocations)
138	        {
139	            if (getObjectAt(location) == null) free.add(location);
140	        }
141	        
142	        return free;
