146	     * Try to find a free location that is adjacent to the
147	     * given location. If there is none, return null.
148	     * The returned location will be within the valid bounds
149	     * of the field.
150	     * 
151	     * @param searchLocation The location from which to generate an adjacency.
152	     * @return A valid location within the grid area.
153	     */
154	    public Location freeAdjacentLocation(Location searchLocation)
155	    {
156	        // Get a list of the free locations:
157	        List<Location> free = getFreeAdjacentLocations(searchLocation);
158	        
