164	    /**
165	     * Return a shuffled list of locations adjacent to the given one.
166	     * The list will not include the location itself.
167	     * All locations will lie within the grid.
168	     * 
169	     * @param location The location from which to generate adjacencies.
170	     * @return A list of locations adjacent to that given.
171	     */
172	    public List<Location> adjacentLocations(Location location)
173	    {
174	        assert location != null : "Null location passed to adjacentLocations";
175	        
176	        // The list of locations to be returned:
177	        List<Location> locations = new ArrayList<>();
178	        
179	        if (location != null)
180	        {
181	            int row = location.getRow();
182	            int col = location.getCol();
183	            
184	            for (int roffset = -1; roffset <= 1; roffset++)
185	            {
186	                int nextRow = row + roffset;
187	                
188	                if (isInsideDepth(nextRow))
189	                {
190	                    for (int coffset = -1; coffset <= 1; coffset++)
191	                    {
192	                        int nextCol = col + coffset;
193	                        
194	                        // Exclude invalid locations and the original location:
195	                        if (isInsideWidth(nextCol) && isDifferentLocation(roffset, coffset))
196	                        {
197	                            locations.add(new Location(nextRow, nextCol));
198	                        }
199	                    }
200	                }
201	            }
202	            
203	            // Shuffle the list. Several other methods rely on the list
204	            // being in a random order:
205	            Collections.shuffle(locations, rand);
206	        }
207	        return locations;
208	    }
